"""Tests of the delivery of agnos-perf-center (FTR-TRC-004, ADR-TRC-009): the tasks closed in git, read from the history's log
(TASK-TRC-057: RQ-TRC-068, RQ-TRC-069, RQ-TRC-071; DEC-TRC-036, DEC-TRC-037).

Run from the repository root: python -m unittest discover -s .github/skills/agnos-perf-center/tests -v
"""
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent / "scripts"))
import agnos_layout  # noqa: E402  RQ-PLG-036: the index and log names, as the scripts read them
sys.path.insert(0, str(HERE))

import history  # noqa: E402
from test_history import RepoTestCase, run_main, setUpModule  # noqa: E402,F401  (setUpModule: an empty git config)

CAROL = "Carol <carol@example.com>"
ALICE = "Alice <alice@example.com>"
BOB = "Bob <bob@example.com>"
CLAUDE = "Claude Opus 5.5 <noreply@anthropic.com>"
GENERATED_AT = "2026-10-24T12:00Z"
PLAN = "process/3.plan/PLAN-ABC-001.md"
FEATURE = "process/1.requirements/FTR-ABC-001.md"
CODE = "src/app.py"
TASKS = ("TASK-ABC-001", "TASK-ABC-002", "TASK-ABC-003", "TASK-ABC-004")
TASK_LINES = 5
INDEX_TEXT = """# AGNOS process index - GENERATED by the agnos-index skill, never edit by hand.
@process/1.requirements/FTR-ABC-001.md
FTR-ABC-001|1-4||Feature
RQ-ABC-001|3-4||First
@process/3.plan/PLAN-ABC-001.md
PLAN-ABC-001|1-22||Plan
TASK-ABC-001|3-7|Done|One
TASK-ABC-002|8-12|Done|Two
TASK-ABC-003|13-17|In Progress|Three
TASK-ABC-004|18-22|Done|Four
"""
FEATURE_TEXT = "# FTR-ABC-001: Feature\n\n### RQ-ABC-001: First\n- **Statement**: the system SHALL work.\n"
CODE_TEXT = "# RQ-ABC-001\ndef f():\n    return 1\n"


def plan(statuses, tiers):
    """The plan document: four tasks of five lines each, from line 3, so that a status change keeps every range."""
    lines = ["# PLAN-ABC-001: Plan", ""]
    for task, status, tier in zip(TASKS, statuses, tiers):
        lines += [f"### {task}: Task", f"- **Tier**: {tier}", f"- **Status**: {status}",
                  "- **Requirement refs**: RQ-ABC-001", ""]
    return "\n".join(lines) + "\n"


class DeliveryTestCase(RepoTestCase):
    """A repository where TASK-ABC-001 is delivered by Alice and Claude, re-tiered and then fixed by Bob; TASK-ABC-002
    is created Done; TASK-ABC-003 is delivered then reopened; TASK-ABC-004 is Done with a comment."""

    def build_repository(self, fix_day=None):
        tiers = ["S", "S", "M", "S"]
        statuses = ["Not Started", "Done", "Not Started", "Not Started"]
        self.repo.commit({f"process/{agnos_layout.INDEX}": INDEX_TEXT, FEATURE: FEATURE_TEXT, PLAN: plan(statuses, tiers),
                          CODE: CODE_TEXT}, author=CAROL, message="docs(ABC): PLAN-ABC-001 planned")
        tiers[0], statuses[0] = "L", "Done"
        self.repo.commit({PLAN: plan(statuses, tiers), CODE: CODE_TEXT.replace("return 1", "return 10")},
                         author=ALICE, co_authors=[CLAUDE], message="feat(ABC): TASK-ABC-001 one")
        statuses[2] = "Done"
        self.repo.commit({PLAN: plan(statuses, tiers)}, author=ALICE, message="feat(ABC): TASK-ABC-003 three")
        statuses[2], statuses[3] = "In Progress", "Done (by the human)"
        self.repo.commit({PLAN: plan(statuses, tiers)}, author=ALICE, message="docs(ABC): TASK-ABC-004 four")
        if fix_day is not None:
            self.repo.day = fix_day - 1
        self.repo.commit({CODE: CODE_TEXT.replace("return 1", "return 11")}, author=BOB,
                         message="fix(ABC): RQ-ABC-001 the value")

    def generate(self, *extra):
        out = self.folder / "out" / "TRACE.html"
        code, text, err = run_main(["--process", str(self.repo.top / "process"), "--sources", str(self.repo.top / "src"),
                                    "--out", str(out), "--generated-at", GENERATED_AT, *extra])
        self.assertEqual(0, code, err)
        return json.loads(out.with_suffix(".json").read_text(encoding="utf-8")), text

    def tasks(self, data):
        return {row[0]: row for row in data["delivery"]["tasks"]}


class DeliveredTaskTest(DeliveryTestCase):
    """RQ-TRC-068, DEC-TRC-036."""

    def setUp(self):
        super().setUp()
        self.build_repository()
        self.data, _ = self.generate("--history")
        self.people = [p["name"] for p in self.data["history"]["people"]]

    def test_RQ_TRC_068_given_a_task_turned_done_then_its_delivery_is_that_commit_with_its_tier_lines_and_type(self):
        task_id, tier, re_tiered, commit, lines, kind, _, reason = self.tasks(self.data)["TASK-ABC-001"]
        delivered = self.data["history"]["commits"][commit]
        self.assertEqual("feat(ABC): TASK-ABC-001 one", delivered["subject"])
        self.assertEqual({"Alice", "Claude Opus 5.5"},
                         {self.people[i] for i in [delivered["author"], *delivered["coAuthors"]]})
        self.assertEqual(("L", True, 2, "feat", None), (tier, re_tiered, lines, kind, reason))

    def test_RQ_TRC_068_given_a_task_created_done_then_it_is_set_aside(self):
        self.assertEqual("created-done", self.tasks(self.data)["TASK-ABC-002"][7])

    def test_RQ_TRC_068_given_a_task_reopened_after_its_delivery_then_it_is_set_aside(self):
        self.assertEqual("reopened", self.tasks(self.data)["TASK-ABC-003"][7])

    def test_RQ_TRC_068_given_a_done_status_with_a_comment_then_it_is_set_aside(self):
        self.assertEqual("annotated", self.tasks(self.data)["TASK-ABC-004"][7])

    def test_RQ_TRC_068_given_a_task_never_done_then_it_is_not_listed(self):
        self.assertEqual(list(TASKS), [row[0] for row in self.data["delivery"]["tasks"]])


class DeliveryBlockTest(DeliveryTestCase):
    """RQ-TRC-069, RQ-TRC-071, DEC-TRC-037."""

    def test_RQ_TRC_069_given_a_history_then_the_block_holds_each_identity_s_active_days_and_the_settings(self):
        self.build_repository()
        data, _ = self.generate("--history")
        names = [p["name"] for p in data["history"]["people"]]
        days = {names[int(i)]: d for i, d in data["delivery"]["activeDays"].items()}
        self.assertEqual({"Carol": ["2026-10-01"], "Alice": ["2026-10-02", "2026-10-03", "2026-10-04"],
                          "Claude Opus 5.5": ["2026-10-02"], "Bob": ["2026-10-05"]}, days)
        settings = json.loads(history.DELIVERY_PATH.read_text(encoding="utf-8"))
        settings.pop(history.SETTINGS_COMMENT_KEY)
        self.assertEqual(settings, data["delivery"]["settings"])
        self.assertNotIn(history.SETTINGS_COMMENT_KEY, data["delivery"]["settings"])    # RQ-MTA-011: a comment is no setting

    def test_RQ_TRC_069_given_no_history_option_then_the_data_file_has_no_delivery(self):
        self.build_repository()
        data, _ = self.generate()
        self.assertNotIn("delivery", data)

    def test_RQ_TRC_071_given_a_fix_citing_the_task_s_requirement_within_the_window_then_the_task_is_reworked(self):
        self.build_repository()
        data, _ = self.generate("--history")
        self.assertTrue(self.tasks(data)["TASK-ABC-001"][6])

    def test_RQ_TRC_071_given_a_fix_after_the_window_then_the_task_is_not_reworked(self):
        self.build_repository(fix_day=25)
        data, _ = self.generate("--history")
        self.assertFalse(self.tasks(data)["TASK-ABC-001"][6])
